WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_definition_single_time_order'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '时间与顺序', 'kp-xingce-judgement-definition-single-time-order', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "定义判断：时间与顺序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定位：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "抓住“在...之前”、“在...之后”、“...期间”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、易错点"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "定义说“在犯罪行为完成之后”，选项说“在准备作案工具时”，时间阶段完全错位，直接排除。"}]}]}$$ AS jsonb), NULL, '时间与顺序的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "时间与顺序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_single_time_order", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
